CREATE OR REPLACE FUNCTION public.finance_can_read() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'accountant') OR public.has_role(auth.uid(),'manager') OR public.has_role(auth.uid(),'leasing_manager')); $$;
REVOKE ALL ON FUNCTION public.finance_can_read() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.finance_can_read() TO authenticated,service_role;
CREATE TABLE IF NOT EXISTS public.payment_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,installments_count integer NOT NULL CHECK(installments_count BETWEEN 1 AND 120),interval_months integer NOT NULL CHECK(interval_months BETWEEN 1 AND 120),due_day integer CHECK(due_day BETWEEN 1 AND 31),is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.payment_plans TO authenticated; GRANT ALL ON public.payment_plans TO service_role;
ALTER TABLE public.payment_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_read ON public.payment_plans FOR SELECT TO authenticated USING(public.finance_can_read());
CREATE TABLE IF NOT EXISTS public.contracts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contract_no text NOT NULL UNIQUE,party_id uuid REFERENCES public.parties(id),booking_id uuid REFERENCES public.bookings(id),start_date date,end_date date,annual_rent_excl_vat numeric(14,2),vat_rate numeric(7,4),payment_plan_id uuid REFERENCES public.payment_plans(id),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','ended','terminated','cancelled')),signed_at timestamptz,documents jsonb NOT NULL DEFAULT '[]',legacy_contract_id uuid UNIQUE REFERENCES public.unit_contracts(id),needs_review boolean NOT NULL DEFAULT false,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),reason text NOT NULL);
GRANT SELECT ON public.contracts TO authenticated; GRANT ALL ON public.contracts TO service_role;
ALTER TABLE public.contracts ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_read ON public.contracts FOR SELECT TO authenticated USING(public.finance_can_read());
CREATE TABLE IF NOT EXISTS public.contract_units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contract_id uuid NOT NULL REFERENCES public.contracts(id),unit_id uuid NOT NULL REFERENCES public.units(id),annual_rent_excl_vat numeric(14,2),UNIQUE(contract_id,unit_id));
GRANT SELECT ON public.contract_units TO authenticated; GRANT ALL ON public.contract_units TO service_role;
ALTER TABLE public.contract_units ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_read ON public.contract_units FOR SELECT TO authenticated USING(public.finance_can_read());
CREATE TABLE IF NOT EXISTS public.installments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contract_id uuid NOT NULL REFERENCES public.contracts(id),sequence_no integer NOT NULL,due_date date NOT NULL,amount_excl_vat numeric(14,2) NOT NULL,vat_amount numeric(14,2) NOT NULL,amount_incl_vat numeric(14,2) NOT NULL,status text NOT NULL DEFAULT 'due' CHECK(status IN ('due','partially_paid','paid','overdue','waived')),waiver_reason text,waived_by uuid,waived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(contract_id,sequence_no),CHECK(amount_excl_vat>=0 AND vat_amount>=0 AND amount_incl_vat=amount_excl_vat+vat_amount));
GRANT SELECT ON public.installments TO authenticated; GRANT ALL ON public.installments TO service_role;
ALTER TABLE public.installments ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_read ON public.installments FOR SELECT TO authenticated USING(public.finance_can_read());
CREATE SEQUENCE IF NOT EXISTS public.receipt_number_seq;
REVOKE ALL ON SEQUENCE public.receipt_number_seq FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS public.receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),receipt_no text NOT NULL UNIQUE DEFAULT ('R-'||lpad(nextval('public.receipt_number_seq')::text,8,'0')),party_id uuid REFERENCES public.parties(id),contract_id uuid REFERENCES public.contracts(id),booking_id uuid REFERENCES public.bookings(id),paid_at timestamptz,method text NOT NULL,amount_excl_vat numeric(14,2) NOT NULL,vat_amount numeric(14,2),amount_incl_vat numeric(14,2),vat_documented boolean NOT NULL DEFAULT true,proof_file text,proof_bucket text NOT NULL DEFAULT 'unit-collection-proofs',recorded_by uuid,verified_by uuid,verified_at timestamptz,status text NOT NULL DEFAULT 'recorded' CHECK(status IN ('recorded','verified','reversed')),reverses_id uuid UNIQUE REFERENCES public.receipts(id),reason text NOT NULL,idempotency_key uuid UNIQUE,archived_at timestamptz,recorded_at timestamptz NOT NULL DEFAULT now(),CHECK((vat_documented AND vat_amount IS NOT NULL AND amount_incl_vat=amount_excl_vat+vat_amount) OR (NOT vat_documented AND vat_amount IS NULL AND amount_incl_vat IS NULL)));
GRANT SELECT ON public.receipts TO authenticated; GRANT ALL ON public.receipts TO service_role;
ALTER TABLE public.receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_read ON public.receipts FOR SELECT TO authenticated USING(public.finance_can_read());
CREATE TABLE IF NOT EXISTS public.receipt_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),receipt_id uuid NOT NULL REFERENCES public.receipts(id),installment_id uuid NOT NULL REFERENCES public.installments(id),amount_excl_vat numeric(14,2) NOT NULL,vat_amount numeric(14,2) NOT NULL,amount_incl_vat numeric(14,2) NOT NULL,reverses_id uuid UNIQUE REFERENCES public.receipt_allocations(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(amount_incl_vat=amount_excl_vat+vat_amount));
GRANT SELECT ON public.receipt_allocations TO authenticated; GRANT ALL ON public.receipt_allocations TO service_role;
ALTER TABLE public.receipt_allocations ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_read ON public.receipt_allocations FOR SELECT TO authenticated USING(public.finance_can_read());
CREATE TABLE IF NOT EXISTS public.receipt_legacy_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_table text NOT NULL CHECK(source_table IN ('unit_collections','invoices')),source_id uuid NOT NULL,receipt_id uuid NOT NULL REFERENCES public.receipts(id),unit_id uuid REFERENCES public.units(id),original_amount numeric NOT NULL,rounded_amount numeric(14,2) NOT NULL,source_recorded_at timestamptz NOT NULL,source_archived boolean NOT NULL DEFAULT false,resolution text NOT NULL DEFAULT 'review' CHECK(resolution IN ('review','distinct','duplicate')),resolution_reason text,resolved_by uuid,resolved_at timestamptz,UNIQUE(source_table,source_id));
GRANT SELECT ON public.receipt_legacy_sources TO authenticated; GRANT ALL ON public.receipt_legacy_sources TO service_role;
ALTER TABLE public.receipt_legacy_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_read ON public.receipt_legacy_sources FOR SELECT TO authenticated USING(public.finance_can_read());
CREATE TABLE IF NOT EXISTS public.finance_cutover(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1),enabled boolean NOT NULL DEFAULT false,enabled_by uuid,enabled_at timestamptz);
GRANT SELECT ON public.finance_cutover TO authenticated; GRANT ALL ON public.finance_cutover TO service_role;
ALTER TABLE public.finance_cutover ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_read ON public.finance_cutover FOR SELECT TO authenticated USING(public.finance_can_read());
CREATE INDEX IF NOT EXISTS installment_due_idx ON public.installments(status,due_date);
CREATE INDEX IF NOT EXISTS receipt_party_date_idx ON public.receipts(party_id,paid_at);
CREATE INDEX IF NOT EXISTS receipt_allocation_installment_idx ON public.receipt_allocations(installment_id);
CREATE INDEX IF NOT EXISTS contract_unit_lookup_idx ON public.contract_units(unit_id);
CREATE OR REPLACE FUNCTION public.finance_audit(_action text,_table text,_id uuid,_before jsonb,_after jsonb,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_log(actor_id,actor_role,action,entity_table,entity_id,before_data,after_data,context) VALUES(auth.uid(),CASE WHEN public.has_role(auth.uid(),'accountant') THEN 'accountant' WHEN public.has_role(auth.uid(),'admin') THEN 'admin' ELSE 'system' END,_action,_table,_id::text,_before,_after,jsonb_build_object('reason',_reason)); END $$;
REVOKE ALL ON FUNCTION public.finance_audit(text,text,uuid,jsonb,jsonb,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.finance_assert_writer() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'accountant')) THEN RAISE EXCEPTION 'إجراء مالي غير مصرح؛ المحاسب أو الأدمن فقط'; END IF; END $$;
REVOKE ALL ON FUNCTION public.finance_assert_writer() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.refresh_installments(_contract uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i record; total numeric; target text; BEGIN IF auth.uid() IS NOT NULL THEN PERFORM public.finance_assert_writer(); ELSIF auth.role() IS DISTINCT FROM 'service_role' AND session_user<>'postgres' THEN RAISE EXCEPTION 'غير مصرح'; END IF; FOR i IN SELECT * FROM public.installments WHERE (_contract IS NULL OR contract_id=_contract) AND status<>'waived' FOR UPDATE LOOP SELECT coalesce(sum(a.amount_incl_vat),0) INTO total FROM public.receipt_allocations a JOIN public.receipts r ON r.id=a.receipt_id WHERE a.installment_id=i.id AND r.status='verified' AND r.reverses_id IS NULL AND r.archived_at IS NULL; target:=CASE WHEN total>=i.amount_incl_vat THEN 'paid' WHEN i.due_date<current_date THEN 'overdue' WHEN total>0 THEN 'partially_paid' ELSE 'due' END; IF target<>i.status THEN UPDATE public.installments SET status=target WHERE id=i.id; PERFORM public.finance_audit('INSTALLMENT_STATUS','installments',i.id,to_jsonb(i),(SELECT to_jsonb(x) FROM public.installments x WHERE id=i.id),'تحديث حالة القسط من التخصيصات المتحققة وتاريخ الاستحقاق'); END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.refresh_installments(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.refresh_installments(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.save_payment_plan(_id uuid,_name text,_count integer,_interval integer,_day integer,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k uuid:=coalesce(_id,gen_random_uuid()); old jsonb; BEGIN PERFORM public.finance_assert_writer(); PERFORM public._assert_reason(_reason); IF nullif(btrim(_name),'') IS NULL THEN RAISE EXCEPTION 'اسم الخطة مطلوب'; END IF; SELECT to_jsonb(p) INTO old FROM public.payment_plans p WHERE id=k FOR UPDATE; IF old IS NOT NULL AND EXISTS(SELECT 1 FROM public.contracts WHERE payment_plan_id=k AND status<>'draft') THEN RAISE EXCEPTION 'الخطة مستخدمة في عقد؛ أنشئ نسخة جديدة بدل تغيير الجدول السابق'; END IF; INSERT INTO public.payment_plans(id,name,installments_count,interval_months,due_day) VALUES(k,btrim(_name),_count,_interval,_day) ON CONFLICT(id) DO UPDATE SET name=excluded.name,installments_count=excluded.installments_count,interval_months=excluded.interval_months,due_day=excluded.due_day,updated_at=now(); PERFORM public.finance_audit('PAYMENT_PLAN_SAVED','payment_plans',k,old,(SELECT to_jsonb(p) FROM public.payment_plans p WHERE id=k),_reason); RETURN k; END $$;
REVOKE ALL ON FUNCTION public.save_payment_plan(uuid,text,integer,integer,integer,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_payment_plan(uuid,text,integer,integer,integer,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.create_contract(_data jsonb,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k uuid:=gen_random_uuid(); item jsonb; BEGIN PERFORM public.finance_assert_writer(); PERFORM public._assert_reason(_reason); IF nullif(btrim(_data->>'contract_no'),'') IS NULL OR (_data->>'party_id') IS NULL OR NOT EXISTS(SELECT 1 FROM public.parties WHERE id=(_data->>'party_id')::uuid AND archived_at IS NULL AND merged_into_id IS NULL) THEN RAISE EXCEPTION 'رقم العقد والعميل الفعّال مطلوبان'; END IF; INSERT INTO public.contracts(id,contract_no,party_id,booking_id,start_date,end_date,annual_rent_excl_vat,vat_rate,payment_plan_id,signed_at,documents,created_by,reason) VALUES(k,btrim(_data->>'contract_no'),(_data->>'party_id')::uuid,nullif(_data->>'booking_id','')::uuid,nullif(_data->>'start_date','')::date,nullif(_data->>'end_date','')::date,(_data->>'annual_rent_excl_vat')::numeric,(_data->>'vat_rate')::numeric,(_data->>'payment_plan_id')::uuid,nullif(_data->>'signed_at','')::timestamptz,coalesce(_data->'documents','[]'),auth.uid(),_reason); FOR item IN SELECT * FROM jsonb_array_elements(coalesce(_data->'units','[]')) LOOP INSERT INTO public.contract_units(contract_id,unit_id,annual_rent_excl_vat) VALUES(k,(item->>'unit_id')::uuid,(item->>'rent')::numeric); END LOOP; PERFORM public.finance_audit('CONTRACT_CREATED','contracts',k,NULL,(SELECT to_jsonb(c) FROM public.contracts c WHERE id=k),_reason); RETURN k; END $$;
REVOKE ALL ON FUNCTION public.create_contract(jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_contract(jsonb,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.activate_contract(_id uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.contracts; p public.payment_plans; n integer; d date; base date; rent numeric; tax numeric; part numeric; taxpart numeric; rentdone numeric:=0; taxdone numeric:=0; u record; BEGIN PERFORM public.finance_assert_writer(); PERFORM public._assert_reason(_reason); SELECT * INTO c FROM public.contracts WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'العقد غير موجود'; END IF; IF c.status='active' THEN RETURN; END IF; IF c.status<>'draft' OR c.needs_review THEN RAISE EXCEPTION 'العقد غير جاهز للتفعيل'; END IF; SELECT * INTO p FROM public.payment_plans WHERE id=c.payment_plan_id; IF NOT FOUND OR NOT p.is_active OR c.start_date IS NULL OR c.end_date IS NULL OR c.end_date<c.start_date OR c.annual_rent_excl_vat IS NULL OR c.annual_rent_excl_vat<=0 OR c.vat_rate IS NULL OR c.vat_rate<0 OR c.vat_rate>100 OR c.signed_at IS NULL THEN RAISE EXCEPTION 'تواريخ العقد وتوقيعه والخطة والأجرة والضريبة مطلوبة'; END IF; IF c.annual_rent_excl_vat<>(SELECT sum(annual_rent_excl_vat) FROM public.contract_units WHERE contract_id=c.id) OR NOT EXISTS(SELECT 1 FROM public.contract_units WHERE contract_id=c.id) OR EXISTS(SELECT 1 FROM public.contract_units WHERE contract_id=c.id AND (annual_rent_excl_vat IS NULL OR annual_rent_excl_vat<=0)) THEN RAISE EXCEPTION 'أجرة الوحدات يجب أن تطابق أجرة العقد'; END IF; FOR u IN SELECT cu.unit_id FROM public.contract_units cu WHERE cu.contract_id=c.id ORDER BY cu.unit_id LOOP PERFORM 1 FROM public.units WHERE id=u.unit_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.contract_units cu JOIN public.contracts x ON x.id=cu.contract_id WHERE cu.unit_id=u.unit_id AND x.status='active' AND x.id<>c.id) OR EXISTS(SELECT 1 FROM public.unit_contracts uc WHERE uc.unit_id=u.unit_id AND uc.status='active' AND NOT EXISTS(SELECT 1 FROM public.contracts cc WHERE cc.legacy_contract_id=uc.id AND cc.id=c.id)) THEN RAISE EXCEPTION 'الوحدة مرتبطة بعقد فعال آخر'; END IF; END LOOP; rent:=c.annual_rent_excl_vat; tax:=round(rent*c.vat_rate/100,2); FOR n IN 1..p.installments_count LOOP base:=(c.start_date+make_interval(months=>(n-1)*p.interval_months))::date; d:=CASE WHEN p.due_day IS NULL THEN base ELSE (date_trunc('month',base)::date+least(p.due_day,extract(day FROM (date_trunc('month',base)+interval '1 month - 1 day'))::integer)-1) END; IF d<c.start_date THEN d:=c.start_date; END IF; IF d>c.end_date THEN RAISE EXCEPTION 'خطة السداد تتجاوز نهاية العقد'; END IF; part:=CASE WHEN n=p.installments_count THEN rent-rentdone ELSE round(rent/p.installments_count,2) END; taxpart:=CASE WHEN n=p.installments_count THEN tax-taxdone ELSE round(tax/p.installments_count,2) END; INSERT INTO public.installments(contract_id,sequence_no,due_date,amount_excl_vat,vat_amount,amount_incl_vat) VALUES(c.id,n,d,part,taxpart,part+taxpart); rentdone:=rentdone+part; taxdone:=taxdone+taxpart; END LOOP; UPDATE public.contracts SET status='active',updated_at=now(),reason=_reason WHERE id=c.id; PERFORM public.finance_audit('CONTRACT_ACTIVATED','contracts',c.id,to_jsonb(c),(SELECT to_jsonb(x) FROM public.contracts x WHERE id=c.id),_reason); PERFORM public.refresh_installments(c.id); END $$;
REVOKE ALL ON FUNCTION public.activate_contract(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.activate_contract(uuid,text) TO authenticated;
SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_name IN ('contracts','contract_units','payment_plans','installments','receipts','receipt_allocations','receipt_legacy_sources');